with valid as (select id, product_name, category, price, cost, stock_qty, launch_date, tags, supplier_id, upper(trim(product_name)) as product_name_normalized, coalesce(price, 0) as price_filled from products where brand is not null and price between 1070 and 1100), base as (select *, date_format(launch_date, 'MMM yyyy') as launch_date_label from valid where cost <= 650), valid_products as (select *, size(tags) as tags_count from base where stock_qty between 313 and 343), metrics as (select *, first_value(tags_count, true) over (partition by supplier_id order by tags_count, id rows between unbounded preceding and current row) as first_known_tags_count, dense_rank() over (partition by supplier_id order by tags_count) as tags_count_dense_rank from valid_products), ranked as (select * from (select *, row_number() over (partition by category order by tags_count, id) as latest_rank from metrics) t where latest_rank = 1), kept as (select s.* from ranked s where not exists (select 1 from store_sales x where x.product_id = s.id and x.product_id in (8, 10))), stats as (select case when cost >= 790 then 'HIGH' else 'LOW' end as cost_tier, supplier_id, category, round(sum(first_known_tags_count) / nullif(count(case when category = 'Electronics' then 1 end), 0), 2) as first_known_tags_count_per_electronics, count_if(category = 'Electronics') as electronics_events from kept group by cost_tier, supplier_id, category) select s.cost_tier, s.supplier_id, s.category, s.first_known_tags_count_per_electronics, s.electronics_events, (select avg(t2.cost) from products t2 where t2.supplier_id = s.supplier_id) as avg_product_cost from stats s order by avg_product_cost desc nulls last, cost_tier
